struct Solution;

impl Solution {
    pub fn sort_colors(nums: &mut Vec<i32>) {
        if nums.is_empty() {
            return;
        }
        let (mut lo, mut i, mut hi) = (0usize, 0usize, nums.len() - 1);
        while i <= hi {
            if nums[i] == 0 {
                nums.swap(i, lo);
                lo += 1;
                i += 1;
            } else if nums[i] == 2 {
                nums.swap(i, hi); // re-check nums[i] next loop
                if hi == 0 {
                    break;
                }
                hi -= 1;
            } else {
                i += 1;
            }
        }
    }
}

