struct Solution;

impl Solution {
    pub fn max_path_sum(root: &Option<Box<TreeNode>>) -> i32 {
        let mut best = std::i32::MIN;
        Self::gain(root, &mut best);
        best
    }

    // best sum of a downward path that starts at this node
    fn gain(node: &Option<Box<TreeNode>>, best: &mut i32) -> i32 {
        match node {
            None => 0,
            Some(n) => {
                let left = Self::gain(&n.left, best).max(0); // drop negative branches
                let right = Self::gain(&n.right, best).max(0);
                *best = (*best).max(n.val + left + right); // path bending here
                n.val + left.max(right)
            }
        }
    }
}

