        if r < 0 || c < 0 || r as usize >= g.len() || c as usize >= g[0].len() || g[r as usize][c as usize] == 0 {
            return 0;
        }
        g[r as usize][c as usize] = 0; // visited
        1 + Self::area(g, r + 1, c) + Self::area(g, r - 1, c) + Self::area(g, r, c + 1) + Self::area(g, r, c - 1)
    }
}

