antiPatterns.good:
use std::fs::File;
use std::io::{self, Write};

fn save(path: &str, data: &str) -> io::Result<()> {
    let mut f = File::create(path)?;
    f.write_all(data.as_bytes())?; // propagate: the caller decides to retry, alert or abort
    f.sync_all()
}
